      pt: "O porto de Algeciras é um centro logístico massivo no extremo sul da Península Ibérica, que cumpre uma função geopolítica entre a Europa e a África, e o Atlântico e o Mediterrâneo. Com um manuseamento constante de mais de 100 milhões de toneladas de carga por ano, domina o rendimento económico marítimo de Espanha. Os terminais estão altamente especializados no transbordo de contentores intercontinental, onde grandes navios descarregam para redistribuir a navios menores. Esta função de nó atrai investimentos contínuos em sistemas de gruas automatizadas. Com cerca de 30.000 empregos diretos e indiretos, funciona como um motor económico indispensável para a região da Andaluzia.",
