imageHint: "Stellantis Vigo automobile factory exterior",
    descriptionAdvanced: {
      de: "Das Stellantis-Werk in Vigo, historisch tief verwurzelt als Produktionsstätte von Citroën, ist heute einer der wichtigsten und produktivsten Standorte des globalen Automobilgiganten. Es bildet das unbestrittene industrielle Herzstück der Region Galicien und zieht ein weitreichendes Netzwerk von Zulieferern und Dienstleistern im gesamten Nordwesten Spaniens nach sich. Die weitläufige Anlage hat sich auf die hochvolumige Produktion von leichten Nutzfahrzeugen, Kompaktwagen und zunehmend auch Elektrofahrzeugen spezialisiert, wodurch sie eine Schlüsselrolle in der europäischen Mobilitätswende einnimmt. Dank der unmittelbaren Nähe zum Atlantikhafen von Vigo verfügt das Werk über herausragende Exportkapazitäten, die es ermöglichen, einen überwältigenden Teil der Tagesproduktion von über 2.000 Fahrzeugen nahtlos in globale Märkte zu verschiffen. Diese Synergie aus Massenproduktion und maritimer Logistik sichert zehntausende direkte und indirekte Arbeitsplätze in der Region.",
      hu: "A történelmileg a Citroën gyártóbázisaként mélyen gyökerező vigói Stellantis gyár ma a globális autóipari óriás egyik legfontosabb és legtermékenyebb telephelye. Galícia régió vitathatatlan ipari szívét képezi, és a beszállítók és szolgáltatók kiterjedt hálózatát vonzza Északnyugat-Spanyolország egész területén. A kiterjedt létesítmény a könnyű haszongépjárművek, kompakt autók és egyre inkább az elektromos járművek nagy volumenű gyártására specializálódott, így kulcsszerepet játszik az európai mobilitási átállásban. A vigói atlanti kikötő közvetlen közelségének köszönhetően a gyár kiemelkedő exportkapacitással rendelkezik, amely lehetővé teszi, hogy a napi több mint 2000 járműből álló termelés túlnyomó részét zökkenőmentesen szállítsák a globális piacokra. A tömegtermelés és a tengeri logisztika ezen szinergiája több tízezer közvetlen és közvetett munkahelyet biztosít a régióban.",
      ro: "Fabrica Stellantis din Vigo, profund înrădăcinată istoric ca bază de producție pentru Citroën, este astăzi una dintre cele mai importante și mai productive locații ale gigantului auto global. Formează inima industrială incontestabilă a regiunii Galiția și atrage o rețea extinsă de furnizori și prestatori de servicii în tot nord-vestul Spaniei. Instalația vastă s-a specializat în producția de volum mare de vehicule utilitare ușoare, mașini compacte și, tot mai mult, vehicule electrice, jucând astfel un rol cheie în tranziția mobilității europene. Datorită apropierii sale imediate de portul atlantic din Vigo, fabrica are capacități remarcabile de export, ceea ce îi permite să expedieze fără probleme o mare parte din producția sa zilnică de peste 2.000 de vehicule pe piețele globale. Această sinergie între producția de masă și logistica maritimă asigură zeci de mii de locuri de muncă directe și indirecte în regiune.",
      en: "The Stellantis plant in Vigo, historically deeply rooted as a production site for Citroën, is today one of the most important and productive locations of the global automotive giant. It forms the undisputed industrial heart of the Galicia region and attracts an extensive network of suppliers and service providers throughout northwestern Spain. The vast facility has specialized in the high-volume production of light commercial vehicles, compact cars, and increasingly electric vehicles, thus playing a key role in the European mobility transition. Thanks to its immediate proximity to the Atlantic port of Vigo, the plant has outstanding export capacities, allowing it to seamlessly ship a vast majority of its daily production of over 2,000 vehicles to global markets. This synergy of mass production and maritime logistics secures tens of thousands of direct and indirect jobs in the region.",
      es: "La planta de Stellantis en Vigo, históricamente arraigada como centro de producción de Citroën, es hoy uno de los sitios más importantes y productivos del gigante automotriz global. Forma el corazón industrial indiscutible de la región de Galicia y atrae a una amplia red de proveedores y proveedores de servicios en todo el noroeste de España. La amplia instalación se ha especializado en la producción de alto volumen de vehículos comerciales ligeros, coches compactos y, cada vez más, también vehículos eléctricos, por lo que juega un papel clave en la transición de movilidad europea. Gracias a la proximidad inmediata al puerto atlántico de Vigo, la planta tiene capacidades de exportación excepcionales que permiten enviar una parte abrumadora de la producción diaria de más de 2.000 vehículos a los mercados globales sin problemas. Esta sinergia de producción en masa y logística marítima asegura decenas de miles de empleos directos e indirectos en la región.",
      pt: "A fábrica da Stellantis em Vigo, historicamente enraizada como centro de produção da Citroën, é hoje um dos locais mais importantes e produtivos do gigante automóvel global. Forma o coração industrial indiscutível da região da Galiza e atrai uma ampla rede de fornecedores e prestadores de serviços em todo o noroeste de Espanha. A ampla instalação especializou-se na produção de alto volume de veículos comerciais ligeiros, carros compactos e, cada vez mais, também veículos elétricos, pelo que desempenha um papel chave na transição da mobilidade europeia. Graças à proximidade imediata ao porto atlântico de Vigo, a fábrica tem capacidades de exportação excecionais que permitem enviar uma parte avassaladora da produção diária de mais de 2.000 veículos para os mercados globais sem problemas. Esta sinergia de produção em massa e logística marítima assegura dezenas de milhares de empregos diretos e indiretos na região.",
      fr: "L'usine Stellantis de Vigo, historiquement ancrée comme centre de production Citroën, est aujourd'hui l'un des sites les plus importants et les plus productifs du géant automobile mondial. Elle forme le cœur industriel incontesté de la région de la Galice et attire un vaste réseau de fournisseurs et de prestataires de services dans tout le nord-ouest de l'Espagne. La vaste installation s'est spécialisée dans la production à haut volume de véhicules utilitaires légers, de voitures compactes et, de plus en plus, de véhicules électriques, jouant ainsi un rôle clé dans la transition de la mobilité européenne. Grâce à la proximité immédiate du port atlantique de Vigo, l'usine dispose de capacités d'exportation exceptionnelles qui permettent d'expédier sans problème une partie écrasante de la production quotidienne de plus de 2 000 véhicules vers les marchés mondiaux. Cette synergie entre production de masse et logistique maritime garantit des dizaines de milliers d'emplois directs et indirects dans la région.",
    },
