      pt: ["Foi fundada originalmente em 1958 como a primeira fábrica da marca francesa Citroën em Espanha", "A capacidade de produção diária em momentos de pico excede os 2000 veículos", "Mais de 85% dos carros produzidos são exportados diretamente para mercados estrangeiros", "A fábrica é o centro europeu líder da plataforma de veículos comerciais (K9) do grupo Stellantis", "Foi construído um importante pavilhão de montagem de baterias para atender aos modelos elétricos", "Contribui por si só com uma parte extremamente significativa do emprego industrial total e do PIB da Galiza"],
      fr: ["A été fondée à l'origine en 1958 comme la première usine de la marque française Citroën en Espagne", "La capacité de production quotidienne aux heures de pointe dépasse les 2 000 véhicules", "Plus de 85 % des voitures produites sont exportées directement vers les marchés étrangers", "L'usine est le centre européen leader de la plateforme de véhicules utilitaires (K9) du groupe Stellantis", "Un important hall d'assemblage de batteries a été construit pour desservir les modèles électriques", "Contribue à elle seule à une part extrêmement importante de l'emploi industriel total et du PIB de la Galice"],
