      de: ["A központból egy globálisan kiterjedt, több mint 7000 üzletből álló hálózatot irányítanak", "A cégcsoport zászlóshajója, a Zara márka minden tervezési és logisztikai döntése itt születik", "A logisztikai elosztóközpont kevesebb mint 48 óra alatt képes árut juttatni bármely kontinensre", "Naponta akár mintegy 5 millió ruhadarab is áthaladhat a teljesen automatizált válogatórendszereken", "Az épületkomplexum kiemelkedő fenntarthatósági és energiatakarékossági tanúsítványokkal bír", "A vállalatot Amancio Ortega alapította, aki ebből a központból irányítva lett a világ egyik leggazdagabb embere"],
