      fr: ["Dirigent un réseau mondial de plus de 7 000 magasins", "Toutes les décisions de design et de logistique de Zara sont prises ici", "Le centre logistique peut envoyer de la marchandise sur n'importe quel continent en moins de 48 heures", "Jusqu'à 5 millions de vêtements peuvent passer chaque jour par les systèmes automatisés", "Le complexe dispose de certifications de durabilité remarquables", "Fondée par Amancio Ortega, devenu l'un des hommes les plus riches du monde"],
