      pt: ["As quatro torres do bairro encabeçam a lista dos edifícios mais altos de Espanha", "A Torre de Cristal, com os seus 249 metros de altura, é a estrutura mais alta do país", "O complexo foi construído inteiramente no local onde se encontrava o antigo complexo desportivo 'Ciudad Deportiva' do Real Madrid", "O projeto começou no início da década de 2000 e foi concluído durante a crise financeira mundial de 2008", "Nos edifícios de escritórios trabalham diariamente mais de dez mil profissionais de finanças e negócios altamente qualificados", "Posteriormente, uma quinta torre (Caleido) também completou o conjunto de edifícios originalmente composto por quatro"],
      fr: ["Les quatre tours du quartier figurent en tête de liste des plus hauts bâtiments d'Espagne", "La Torre de Cristal, avec ses 249 mètres de hauteur, est la plus haute structure du pays", "Le complexe a été construit entièrement à l'emplacement de l'ancien complexe sportif 'Ciudad Deportiva' du Real Madrid", "Le projet a débuté au début des années 2000 et s'est achevé pendant la crise financière mondiale de 2008", "Plus de dix mille professionnels de la finance et des affaires hautement qualifiés travaillent quotidiennement dans les immeubles de bureaux", "Par la suite, une cinquième tour (Caleido) est venue compléter l'ensemble de bâtiments composé à l'origine de quatre tours"],
