      pt: ["Mais de 115 edifícios industriais históricos foram salvos", "Mais de 10.000 empresas estabelecidas", "A área abrange 200 hectares", "Ecossistema de conhecimento formado por tech, unis e startups", "A Torre Glòries é um símbolo visual fundamental", "Integração de transporte público, bicicletas e áreas verdes"],
      fr: ["Plus de 115 bâtiments industriels historiques ont été sauvés", "Plus de 10 000 entreprises établies", "La zone couvre 200 hectares", "Écosystème de connaissances formé par des entreprises technologiques, des universités et des startups", "La tour Glòries est un symbole visuel clé", "Intégration des transports publics, des vélos et des espaces verts"],
