      en: [],
      es: ["La historia documentada de la actividad minera abarca más de cinco mil años", "A finales del siglo XIX, el cobre extraído aquí representaba más del 10% de la producción mundial total de cobre", "El valor de pH extremadamente alto (alrededor de 2) del río alberga microorganismos raros tolerantes a los ácidos", "La mina llamada Corta Atalaya fue una vez la mina a cielo abierto más ancha y profunda de Europa", "La compra de las minas en 1873 sentó las bases del grupo multinacional minero global Rio Tinto", "La colonia británica encontrada en el área es un ejemplo único de arquitectura victoriana en Andalucía"],
      pt: ["A história documentada da atividade mineira abarca mais de cinco mil anos", "No final do século XIX, o cobre extraído aqui representava mais de 10% da produção mundial total de cobre", "O valor de pH extremamente alto (cerca de 2) do rio alberga microrganismos raros tolerantes a ácidos", "A mina chamada Corta Atalaya foi outrora a mina a céu aberto mais larga e profunda da Europa", "A compra das minas em 1873 lançou as bases do grupo multinacional mineiro global Rio Tinto", "A colónia britânica encontrada na área é um exemplo único de arquitetura vitoriana na Andaluzia"],
      fr: ["L'histoire documentée de l'activité minière s'étend sur plus de cinq mille ans", "À la fin du XIXe siècle, le cuivre extrait ici représentait plus de 10 % de la production mondiale totale de cuivre", "Le pH extrêmement élevé (environ 2) de la rivière abrite des micro-organismes rares tolérants aux acides", "La mine appelée Corta Atalaya était autrefois la mine à ciel ouvert la plus large et la plus profonde d'Europe", "Le rachat des mines en 1873 a jeté les bases du groupe minier multinational mondial Rio Tinto", "La colonie britannique trouvée dans la région est un exemple unique d'architecture victorienne en Andalousie"],
