      pt: ["A construção começou em 1964 sob os planos de desenvolvimento estatais de Franco", "Alberga a segunda maior refinaria de petróleo de Espanha (propriedade da CEPSA)", "Cria mais de 8.000 empregos diretos e 30.000 indiretos em Huelva", "Lar de uma das fundições e refinarias de cobre mais importantes da Europa (Atlantic Copper)", "Acumularam-se cerca de 120 milhões de toneladas de fosfogesso radioativo na zona", "Grande parte da produção química é exportada imediatamente através do porto"],
      fr: ["La construction a commencé en 1964 sous les plans de développement étatiques de Franco", "Abrite la deuxième plus grande raffinerie de pétrole d'Espagne (propriété de CEPSA)", "Crée plus de 8 000 emplois directs et 30 000 indirects à Huelva", "Siège de l'une des fonderies et raffineries de cuivre les plus importantes d'Europe (Atlantic Copper)", "Environ 120 millions de tonnes de phosphogypse radioactif se sont accumulées dans la zone", "Une grande partie de la production chimique est immédiatement exportée via le port"],
