      pt: ["A instalação de testes conta com mais de 3000 horas de sol limpo e utilizável por ano", "O centro foi estabelecido no início dos anos oitenta sob a influência das crises petrolíferas internacionais", "Opera duas torres solares separadas de 43 e 80 metros de altura para levar a cabo fases experimentais", "Uma área de investigação chave é a dessalinização, desenvolvendo sistemas de purificação de água que funcionam com energia solar", "É o local de teste mais importante para profissionais dos estados membros da União Europeia na indústria da energia solar", "Na sua área de mais de 100 hectares, são investigadas quase todas as tecnologias de energia solar concentrada existentes"],
      fr: ["L'installation d'essai bénéficie de plus de 3 000 heures de soleil propre et utilisable par an", "Le centre a été créé au début des années quatre-vingt sous l'influence des crises pétrolières internationales", "Exploite deux tours solaires distinctes de 43 et 80 mètres de haut pour mener les phases expérimentales", "Un domaine de recherche clé est le dessalement, avec le développement de systèmes de purification d'eau fonctionnant à l'énergie solaire", "C'est le site d'essai le plus important pour les professionnels des États membres de l'Union européenne dans l'industrie de l'énergie solaire", "Sur sa zone de plus de 100 hectares, presque toutes les technologies d'énergie solaire concentrée existantes sont étudiées"],
