      es: ["Primera central comercial del mundo con almacenamiento de sales fundidas (inaugurada en 2011)", "Cada uno de los 2.650 helióstatos tiene una superficie reflectante de 120 metros cuadrados", "Capaz de generar electricidad las 24 horas la mayoría de los días del año", "La torre central se eleva 140 metros sobre el paisaje andaluz", "Suministra energía a unos 25.000 hogares españoles", "Evita la emisión de 30.000 toneladas de CO2 al año al sustituir combustibles fósiles"],
      pt: ["Primeira central comercial do mundo com armazenamento de sais fundidos (inaugurada em 2011)", "Cada um dos 2.650 helióstatos tem uma superfície refletora de 120 metros quadrados", "Capaz de gerar eletricidade 24 horas na maioria dos dias do ano", "A torre central eleva-se a 140 metros sobre a paisagem andaluza", "Fornece energia a cerca de 25.000 lares espanhóis", "Evita a emissão de 30.000 toneladas de CO2 por ano ao substituir combustíveis fósseis"],
      fr: ["Première centrale commerciale au monde avec stockage de sels fondus (inaugurée en 2011)", "Chacun des 2 650 héliostats a une surface réfléchissante de 120 mètres carrés", "Capable de générer de l'électricité 24h/24 la plupart des jours de l'année", "La tour centrale s'élève à 140 mètres au-dessus du paysage andalou", "Fournit de l'énergie à environ 25 000 foyers espagnols", "Évite l'émission de 30 000 tonnes de CO2 par an en remplaçant les combustibles fossiles"],
