      de: "Die Raffinerie im Escombreras-Tal bei Cartagena ist eine der größten und effizientesten in Europa. Sie spielt eine Schlüsselrolle in der spanischen Kraftstoffversorgung.",
      hu: "A Cartagena melletti Escombreras-völgyben található finomító Európa egyik legnagyobb és leghatékonyabb létesítménye. Kulcsszerepet játszik Spanyolország üzemanyag-ellátásában.",
      ro: "Rafinăria din Valea Escombreras, lângă Cartagena, este una dintre cele mai mari și mai eficiente din Europa. Joacă un rol cheie în aprovizionarea cu combustibil a Spaniei.",
      en: "The refinery in the Escombreras Valley near Cartagena is one of the largest and most efficient in Europe. It plays a key role in Spain's fuel supply.",
      es: "La refinería en el valle de Escombreras cerca de Cartagena es una de las más grandes y eficientes de Europa. Desempeña un papel clave en el suministro de combustible español.",
