      fr: ["L'agrandissement gigantesque achevé en 2012 (projet C-10) a représenté un investissement de plus de 3 milliards d'euros", "Sa capacité de raffinage atteint 11 millions de tonnes par an, assurant l'approvisionnement énergétique du pays", "Elle dispose de l'une des plus grandes unités de récupération de soufre et de cokéfaction (coker) au monde pour le traitement des pétroles bruts lourds", "Un réseau direct d'oléoducs la relie au complexe industriel et de raffinage terrestre de Puertollano", "Elle est leader dans l'industrie de la production de biocarburants à partir d'huiles de cuisson usagées et de déchets agro-industriels", "Grâce à ses installations portuaires, c'est l'un des centres énergétiques les mieux positionnés sur le plan logistique en Europe"],
