      es: ["El 94% de toda la producción española de azulejos y baldosas se concentra en esta única provincia", "El ecosistema de la industria cerámica sostiene más de 15.000 puestos de trabajo directos y unos 20.000 indirectos en la región", "Los fabricantes producen más de 500 millones de metros cuadrados de materiales cerámicos al año", "El sector contribuye al PIB nacional con unos ingresos por exportación de casi 3.000 millones de euros anuales", "Desempeña un papel líder en el desarrollo global de tecnologías de impresión digital de azulejos (inkjet)", "Las crisis debidas a los altos precios del gas natural han obligado al clúster a probar hornos alimentados con hidrógeno verde"],
      pt: ["94% de toda a produção espanhola de azulejos e mosaicos concentra-se nesta única província", "O ecossistema da indústria cerâmica sustenta mais de 15.000 postos de trabalho diretos e cerca de 20.000 indiretos na região", "Os fabricantes produzem mais de 500 milhões de metros quadrados de materiais cerâmicos por ano", "O setor contribui para o PIB nacional com receitas de exportação de quase 3.000 milhões de euros anuais", "Desempenha um papel líder no desenvolvimento global de tecnologias de impressão digital de azulejos (inkjet)", "As crises devido aos altos preços do gás natural obrigaram o cluster a testar fornos alimentados com hidrogénio verde"],
      fr: ["94 % de toute la production espagnole de carreaux et de dalles est concentrée dans cette seule province", "L'écosystème de l'industrie céramique soutient plus de 15 000 emplois directs et environ 20 000 emplois indirects dans la région", "Les fabricants produisent plus de 500 millions de mètres carrés de matériaux céramiques par an", "Le secteur contribue au PIB national avec des revenus d'exportation de près de 3 milliards d'euros par an", "Il joue un rôle de leader dans le développement mondial des technologies d'impression numérique sur carreaux (jet d'encre)", "Les crises dues aux prix élevés du gaz naturel ont contraint le pôle à tester des fours alimentés à l'hydrogène vert"],
