    parent: "ES",
    type: "port",
    name: { de: "Industriehafen von Sagunto", hu: "Saguntói ipari kikötő", ro: "Portul Industrial Sagunto", en: "Sagunto Industrial Port"},
    image: "/poi-images/spain-sagunto-industrial-port-economic-v2.webp",
    coords: [-0.2167, 39.65],
