      pt: ["Propriedade a 100% da multinacional canadiana First Quantum Minerals", "A extração de cobre realiza-se através de um processo químico húmido chamado hidrometalurgia", "Fabrica cátodos de cobre de 'Grau A' (99,999%) diretamente no local", "A mineração centra-se progressivamente em corpos mineralizados polimetálicos mais profundos", "Mantêm um sistema de monitorização rigoroso para proteger os recursos hídricos locais", "É um dos empregadores mais destacados da província de Sevilha com cerca de 800 funcionários"],
