      es: ["Gran parte de la producción total de electricidad de España proviene de las centrales de ciclo combinado del valle", "La terminal local de Enagás puede recibir y regasificar cientos de miles de metros cúbicos de GNL anualmente", "El complejo lidera proyectos de hidrógeno verde con enormes inversiones", "Plantas desalinizadoras propias garantizan el agua industrial necesaria", "Más de 200 empresas operan diariamente dentro del valle", "Aproximadamente el 80% del tráfico de carga del puerto de Cartagena proviene de Escombreras"],
      pt: ["Grande parte da produção total de eletricidade de Espanha provém das centrais de ciclo combinado do vale", "O terminal local da Enagás pode receber e regasificar centenas de milhares de metros cúbicos de GNL anualmente", "O complexo lidera projetos de hidrogénio verde com enormes investimentos", "Estações de dessalinização próprias garantem a água industrial necessária", "Mais de 200 empresas operam diariamente dentro do vale", "Aproximadamente 80% do tráfego de carga do porto de Cartagena provém de Escombreras"],
      fr: ["Une grande partie de la production totale d'électricité de l'Espagne provient des centrales à cycle combiné de la vallée", "Le terminal local d'Enagás peut recevoir et regazéifier des centaines de milliers de mètres cubes de GNL par an", "Le complexe dirige des projets d'hydrogène vert avec d'énormes investissements", "Des usines de dessalement propres garantissent l'eau industrielle nécessaire", "Plus de 200 entreprises opèrent quotidiennement dans la vallée", "Environ 80 % du trafic de fret du port de Carthagène provient d'Escombreras"],
