      pt: ["Mais de 30 grandes empresas químicas globais operam no complexo", "Contribui com cerca de um quarto da produção química total da Espanha", "Consiste em dois grandes subcentros ligados por uma densa rede de tubagens", "Colabora estreitamente com a universidade local em inovações de reciclagem de plástico", "O cluster gera cerca de 40.000 empregos diretos, indiretos e induzidos", "Produz anualmente cerca de 20 milhões de toneladas de produtos petroquímicos"],
      fr: ["Plus de 30 grandes entreprises chimiques mondiales opèrent sur le complexe", "Fournit environ un quart de la production chimique totale de l'Espagne", "Se compose de deux grands sous-centres reliés par un réseau dense de pipelines", "Collabore étroitement avec l'université locale sur les innovations en matière de recyclage des plastiques", "Le cluster génère environ 40 000 emplois directs, indirects et induits", "Produit environ 20 millions de tonnes de produits pétrochimiques par an"],
