      en: "The 'la Caixa de Guissona' model is a unique example of vertically integrated food production. It is one of the largest agricultural companies in Spain.",
      es: "El modelo 'la Caixa de Guissona' es un ejemplo único de producción alimentaria integrada verticalmente. Es una de las mayores empresas agrarias de España.",
