      es: ["El modelo integrado de la empresa (bonÀrea Agrupa) cuenta con más de 500 tiendas propias en la Península", "En el centro industrial del pueblo trabajan unas 5.000 personas diariamente", "Se abastece exclusivamente de explotaciones asociadas propias para garantizar la trazabilidad", "Capacidad diaria de procesamiento superior a cientos de miles de aves y miles de cerdos y vacunos", "La logística automatizada asegura que la carne se venda el mismo día del sacrificio", "Facturación anual que supera ampliamente los 2.000 millones de euros"],
      pt: ["O modelo integrado da empresa (bonÀrea Agrupa) conta com mais de 500 lojas próprias na Península", "No centro industrial da vila trabalham cerca de 5.000 pessoas diariamente", "Abastece-se exclusivamente de explorações associadas próprias para garantir a rastreabilidade", "Capacidade diária de processamento superior a centenas de milhares de aves e milhares de porcos e bovinos", "A logística automatizada assegura que a carne seja vendida no mesmo dia do abate", "Faturação anual que supera largamente os 2 mil milhões de euros"],
      fr: ["Le modèle intégré de l'entreprise (bonÀrea Agrupa) compte plus de 500 magasins en propre dans la péninsule", "Environ 5 000 personnes travaillent quotidiennement dans le centre industriel du village", "S'approvisionne exclusivement auprès de ses propres exploitations partenaires pour garantir la traçabilité", "Capacité de transformation quotidienne supérieure à des centaines de milliers de volailles et des milliers de porcs et bovins", "La logistique automatisée garantit que la viande est vendue le jour même de l'abattage", "Chiffre d'affaires annuel dépassant largement les 2 milliards d'euros"],
