      hu: ["Az intézményt 1992 decemberében adták át", "Több mint 650 vállalat működik a 168 hektáros területen", "A parkban foglalkoztatottak száma meghaladja a 25 000 főt", "Olyan cégek központja, mint az Ericsson, az Oracle és a Google", "Szoros partnerségben áll a Málagai Egyetemmel", "A Tudományos Parkok Nemzetközi Szövetségének (IASP) tagja"],
